with creado as (insert into public.piloto_menus_completos(slug,original,borrador,plan) select 'shopping-morales',p,p,'normal' from (select '{"nombre":"Shopping Morales","slug":"shopping-morales","categoria":"cat-ropa-calzado-y-accesorios","descripcion":"Ropa nueva americana seleccionada, con marcas como Calvin Klein, Levi’s, Adidas, Zara, Fashion Nova y más. También cuentan con accesorios, joyería fina, bolsas, regalos y abarrotes en general, para que puedas encontrar diferentes productos en un mismo lugar.","telefono":"9631858534","whatsapp":"9631858534","tipoCatalogo":"visual","activo":true,"verificado":false,"delivery":false,"mostrarGaleria":false,"productos":[],"galeria":[],"servicios":[],"horarios":{"lunes":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"martes":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"miercoles":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"jueves":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"viernes":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"sabado":{"modo":"abierto","turnos":[{"inicio":"07:00","fin":"21:30"}]},"domingo":{"modo":"sin_confirmar","turnos":[]}}}'::jsonb || jsonb_build_object('id',floor(extract(epoch from clock_timestamp())*1000)) p) x where not exists(select 1 from public.piloto_menus_completos where slug='shopping-morales') returning *) insert into public.sitio_historial(tipo,registro,anterior,nuevo,actor) select 'negocios',slug,'{}'::jsonb,original-'productos',null from creado returning registro;